    print("title:",pg.inner_text("#v-invest h1"),"| amount:",pg.input_value("#v-invest .amt input"),"| fee:",pg.inner_text("#v-invest .fe"),"| total:",pg.inner_text("#v-invest .to"),"| next disabled:",pg.is_disabled("#v-invest .nx"))
    pg.screenshot(path="p4-invest1.png")
    pg.fill("#v-invest .amt input","50"); print("err:",pg.inner_text("#v-invest .er"))
    pg.click("#v-invest [data-q='1000']"); print("quick chip amount:",pg.input_value("#v-invest .amt input"))
    pg.fill("#v-invest .amt input","400")
    for k in [0,1,2]: pg.click(f"#v-invest [data-k='{k}']")
    print("next enabled after acks:",not pg.is_disabled("#v-invest .nx")); pg.screenshot(path="p4-invest1b.png")
    pg.click("#v-invest .nx"); pg.wait_for_timeout(100); print("step2:",pg.inner_text("#v-invest h1")); 
    print("next disabled:",pg.is_disabled("#v-invest .nx"))
    pg.click("#v-invest [data-m=momo]"); pg.click("#v-invest [data-p='MTN MoMo']"); pg.fill("#v-invest #ph","024 123 4567"); pg.screenshot(path="p4-invest2.png")
    print("next enabled:",not pg.is_disabled("#v-invest .nx")); pg.click("#v-invest .nx"); pg.wait_for_timeout(100); print("step3:",pg.inner_text("#v-invest h1")); pg.screenshot(path="p4-invest3.png")
    pg.click("#v-invest .back"); print("back to:",pg.inner_text("#v-invest h1")); pg.click("#v-invest .nx")
