    pg.click("#v-invest .back") if pg.query_selector("#v-invest .back") else None
    pg.wait_for_timeout(2000); print("result:",pg.inner_text("#v-invest h1"),"|",pg.inner_text("#v-invest .rf")[:14]); pg.screenshot(path="p4-invest-done.png")
    pg.click("#v-invest [data-a=port]"); pg.wait_for_timeout(100); ov("->portfolio")
    print("portfolio total:",pg.inner_text("#v-portfolio .big")[:6],"| positions:",pg.evaluate("document.querySelectorAll('#v-portfolio .ph2').length"))
    pg.click("#v-portfolio [data-o=zuri]"); print("expanded ref:",pg.inner_text("#v-portfolio .pd:not([hidden]) .sm b >> nth=3")[:4]); pg.screenshot(path="p4-portfolio.png")
    pg.click("#v-portfolio .pd:not([hidden]) [data-deal]"); pg.wait_for_timeout(700); print("view round:",pg.inner_text("#v-deal h1")); pg.click("#v-deal .back")
    pg.click("#v-portfolio .back"); pg.click("#nav [data-go=you]"); print("you panel:",pg.inner_text("#v-you .panel .big"),"| rows:",pg.evaluate("document.querySelectorAll('#v-you .panel .pos').length"))
    pg.click("#v-you h2 a[data-view=portfolio]"); ov("you history->portfolio")
    # failed payment (0000) + offline
    pg.click("#nav [data-go=capital]") if not pg.evaluate("document.getElementById('nav').hidden") else pg.click("#v-portfolio .back")
    pg.click("#nav [data-go=capital]"); pg.click("#v-capital .rd[data-deal=aya]"); pg.wait_for_timeout(700); pg.click("#v-deal .go"); 
    for k in [0,1,2]: pg.click(f"#v-invest [data-k='{k}']")
    pg.click("#v-invest .nx"); pg.click("#v-invest [data-m=momo]"); pg.click("#v-invest [data-p='AirtelTigo']"); pg.fill("#v-invest #ph","0240000000" if False else "0240010000"); pg.click("#v-invest .nx"); pg.click("#v-invest [data-a=pay]"); pg.wait_for_timeout(2200)
    print("decline result:",pg.inner_text("#v-invest h1")); pg.screenshot(path="p4-invest-fail.png")
