    pg.evaluate("App.tab('capital')"); pg.wait_for_timeout(600); pg.click("#v-capital .p3a [data-view=watch]"); ov("->watch"); print("watch rows:",pg.evaluate("document.querySelectorAll('#v-watch .wr').length")); pg.screenshot(path="p4-watch.png")
    pg.click("#v-watch [data-w=zuri]"); print("after unwatch:",pg.evaluate("document.querySelectorAll('#v-watch .wr').length"))
    pg.click("#v-watch .back"); print("capital watching stat:",pg.inner_text("#v-capital .pf .g div:nth-child(3) strong"))
    pg.click("#v-capital .rd[data-deal=zuri]"); pg.wait_for_timeout(700); print("zuri watch pressed:",pg.get_attribute("#v-deal .wt","aria-pressed")); pg.click("#v-deal .wt"); print("after toggle:",pg.get_attribute("#v-deal .wt","aria-pressed"),"| stat:",pg.inner_text("#v-capital .pf .g div:nth-child(3) strong")); pg.click("#v-deal .back")
    # --- compare
    pg.click("#v-capital .p3a [data-view=compare]"); ov("->compare"); pg.screenshot(path="p4-compare.png")
    pg.click("#v-compare [data-c='Bzuri']"); print("headers:",pg.evaluate("[...document.querySelectorAll('#v-compare .cm th')].map(t=>t.textContent).join('|')"))
    pg.click("#v-compare [data-c='Bkora']"); pg.click("#v-compare [data-c='Akora']"); print("swap headers:",pg.evaluate("[...document.querySelectorAll('#v-compare .cm th')].map(t=>t.textContent).join('|')"))
    pg.screenshot(path="p4-compare2.png")
    pg.click("#v-compare [data-deal=kora]"); pg.wait_for_timeout(700); print("open from compare:",pg.inner_text("#v-deal h1")); pg.click("#v-deal .back"); pg.click("#v-compare .back")
    # --- AI
    pg.click("#nav [data-go=home]"); pg.click("#v-home .askf"); pg.wait_for_timeout(200); ov("home->ai"); print("focused:",pg.evaluate("document.activeElement.getAttribute('aria-label')")); pg.screenshot(path="p4-ai.png")
    pg.click("#v-ai [data-s='Compare Aya Health and Kora Freight']"); pg.wait_for_timeout(300); print("thinking:",pg.evaluate("!!document.querySelector('#v-ai .th2')")); pg.wait_for_timeout(1000)
    print("answer sources:",pg.evaluate("[...document.querySelectorAll('#v-ai .sr button')].map(b=>b.textContent).join(', ')")); pg.screenshot(path="p4-ai-answer.png")
    pg.fill("#v-ai .tin input","What are the risks of Zuri Energy?"); pg.press("#v-ai .tin input","Enter"); pg.wait_for_timeout(1300)
    print("risk answer bullets:",pg.evaluate("document.querySelectorAll('#v-ai .am:last-child li').length"))
    pg.fill("#v-ai .tin input","Who is Ama Boateng?"); pg.press("#v-ai .tin input","Enter"); pg.wait_for_timeout(1300)
    pg.click("#v-ai .am:last-child .sr button >> nth=0"); ov("source->profile")
    pg.click("#v-profile .back") if False else pg.evaluate("App.back()")
    pg.fill("#v-ai .tin input","How does investing work?"); pg.press("#v-ai .tin input","Enter"); pg.wait_for_timeout(1300); print("safe answer:",pg.inner_text("#v-ai .am:last-child p >> nth=0")[:40])
    pg.fill("#v-ai .tin input","What is the weather?"); pg.press("#v-ai .tin input","Enter"); pg.wait_for_timeout(1300); print("fallback:",pg.inner_text("#v-ai .am:last-child p >> nth=0")[:40])
    pg.emulate_media(color_scheme="dark"); pg.wait_for_timeout(150); pg.screenshot(path="p4-ai-dark.png")
    print("ERRORS:",errs)
    b.close()
